/* @autogenerated */
import { BehaviorSubject, Observable } from 'rxjs';

type Entries<T> = { [key: string]: { cache: CacheResource<T>; observers: number } };

/** Valor cacheado con caducidad; se borra de su mapa cuando deja de tener observadores. */
export class CacheResource<T> {
  private expires: number;
  private readonly value: BehaviorSubject<T | undefined>;

  constructor(
    private readonly entries: Entries<T>,
    private readonly key: string,
    private readonly ttl: () => number,
    value?: T,
  ) {
    this.value = new BehaviorSubject<T | undefined>(value);
    this.expires = value ? Date.now() + ttl() : 0;
  }

  evict() {
    this.expires = 0;
  }

  isExpired() {
    return this.expires < Date.now();
  }

  currentValue(): T | undefined {
    return this.value.value;
  }

  observable(): Observable<T | undefined> {
    return new Observable((observer) => {
      const entry = this.entries[this.key];
      if (entry) {
        ++entry.observers;
      }
      const subscription = this.value.subscribe((value) => observer.next(value));
      return () => {
        subscription.unsubscribe();
        // Tras un clear() la clave puede pertenecer ya a otra entrada: solo se borra la propia
        if (entry && --entry.observers <= 0 && this.entries[this.key] === entry) {
          delete this.entries[this.key];
        }
      };
    });
  }

  remove() {
    if (this.entries[this.key]?.cache === this) {
      delete this.entries[this.key];
    }
  }

  wait(obs: Observable<T>) {
    this.markWaiting();
    return obs.subscribe((data) => this.touch(data));
  }

  markWaiting() {
    this.expires = Date.now() + this.ttl();
  }

  touch(value?: T) {
    if (JSON.stringify(this.value.value ?? '') !== JSON.stringify(value ?? '')) {
      this.value.next(value);
    }
    this.expires = Date.now() + this.ttl();
  }
}
